package com.nexusdrive.metadata.dto;import com.nexusdrive.metadata.entity.FileMetadata;import java.time.Instant;import java.util.*;public record FileResponse(UUID id,String filename,String mimeType,long sizeBytes,String contentHash,String status,List<String> tags,Instant createdAt){public static FileResponse from(FileMetadata f){return new FileResponse(f.getId(),f.getFilename(),f.getMimeType(),f.getSizeBytes(),f.getContentHash(),f.getStatus().name(),Arrays.asList(f.getTags()),f.getCreatedAt());}}
